-- [JLAS-W0108] Approved Smart Test N3 corrections
-- N3-020 distractors are already corrected in questionbank.sql for fresh installs.
-- This guarded repair converges older rows only when no learner has seen them.
START TRANSACTION;

UPDATE assessment_question q
SET q.option_1 = '教室',
    q.option_2 = '校庭',
    q.option_3 = '階段'
WHERE q.skill = 'KANJI'
  AND q.jlpt_level = 'N3'
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) = 'KANJI-DIVERSE-N3-020'
  AND q.answer_text = '廊下'
  AND q.correct_option = 4
  AND q.option_1 = '取る'
  AND q.option_2 = '引く'
  AND q.option_3 = '押す'
  AND q.option_4 = '廊下'
  AND NOT EXISTS (SELECT 1 FROM smart_test_session_question sq WHERE sq.question_id = q.id)
  AND NOT EXISTS (SELECT 1 FROM assessment_answer a WHERE a.question_id = q.id);

SELECT ROW_COUNT() AS repaired_rows;
COMMIT;

SELECT q.id, q.option_1, q.option_2, q.option_3, q.option_4,
       q.correct_option, q.answer_text
FROM assessment_question q
WHERE JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) = 'KANJI-DIVERSE-N3-020';

-- Owner-approved N3 Kanji JLPT retag (2026-10-13); idempotent for existing databases.
SET NAMES utf8mb4;
START TRANSACTION;

UPDATE assessment_question q
SET q.context_json = JSON_ARRAY_APPEND(q.context_json, '$.additional_tags', 'JLPT')
WHERE q.skill = 'KANJI'
  AND q.jlpt_level = 'N3'
  AND q.is_active = 1
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) = 'KANJI_N5_N1_DIVERSE_V3'
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) IN (
      'KANJI-DIVERSE-N3-001', 'KANJI-DIVERSE-N3-004',
      'KANJI-DIVERSE-N3-006', 'KANJI-DIVERSE-N3-007',
      'KANJI-DIVERSE-N3-010', 'KANJI-DIVERSE-N3-013',
      'KANJI-DIVERSE-N3-022', 'KANJI-DIVERSE-N3-023',
      'KANJI-DIVERSE-N3-024', 'KANJI-DIVERSE-N3-025',
      'KANJI-DIVERSE-N3-026', 'KANJI-DIVERSE-N3-027',
      'KANJI-DIVERSE-N3-028', 'KANJI-DIVERSE-N3-030',
      'KANJI-DIVERSE-N3-031', 'KANJI-DIVERSE-N3-032',
      'KANJI-DIVERSE-N3-034', 'KANJI-DIVERSE-N3-037',
      'KANJI-DIVERSE-N3-038', 'KANJI-DIVERSE-N3-041')
  AND JSON_TYPE(JSON_EXTRACT(q.context_json, '$.additional_tags')) = 'ARRAY'
  AND NOT JSON_CONTAINS(JSON_EXTRACT(q.context_json, '$.additional_tags'), JSON_QUOTE('JLPT'))
  AND q.answer_text = ELT(q.correct_option, q.option_1, q.option_2, q.option_3, q.option_4)
  AND q.option_1 <> q.option_2 AND q.option_1 <> q.option_3 AND q.option_1 <> q.option_4
  AND q.option_2 <> q.option_3 AND q.option_2 <> q.option_4 AND q.option_3 <> q.option_4;

SELECT ROW_COUNT() AS newly_retagged_rows;
COMMIT;

SELECT COUNT(*) AS candidate_rows_with_jlpt_tag,
       COUNT(DISTINCT JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.lexeme'))) AS distinct_lexemes
FROM assessment_question q
WHERE JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) IN (
      'KANJI-DIVERSE-N3-001', 'KANJI-DIVERSE-N3-004',
      'KANJI-DIVERSE-N3-006', 'KANJI-DIVERSE-N3-007',
      'KANJI-DIVERSE-N3-010', 'KANJI-DIVERSE-N3-013',
      'KANJI-DIVERSE-N3-022', 'KANJI-DIVERSE-N3-023',
      'KANJI-DIVERSE-N3-024', 'KANJI-DIVERSE-N3-025',
      'KANJI-DIVERSE-N3-026', 'KANJI-DIVERSE-N3-027',
      'KANJI-DIVERSE-N3-028', 'KANJI-DIVERSE-N3-030',
      'KANJI-DIVERSE-N3-031', 'KANJI-DIVERSE-N3-032',
      'KANJI-DIVERSE-N3-034', 'KANJI-DIVERSE-N3-037',
      'KANJI-DIVERSE-N3-038', 'KANJI-DIVERSE-N3-041')
  AND JSON_CONTAINS(JSON_EXTRACT(q.context_json, '$.additional_tags'), JSON_QUOTE('JLPT'));

